-- ============================================================
-- SEED EXT 4: Módulo 23 — Advanced Modals (ex 143-215)
-- Novos tópicos: modais perfeitos em inferência, modais em academic
-- hedging avançado, semi-modais (ought to/need to/dare to/used to),
-- modais passivos em resultados de pesquisa
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'advanced-modals';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo advanced-modals não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 41: Modais perfeitos — dedução e inferência sobre o passado
  (cid,41,143,'multiple_choice','What is the difference: "They must have miscalculated" vs "They might have miscalculated"?','"Must have" = logical deduction (certainty based on evidence). "Might have" = mere possibility.','["No difference","''Must have'' = certainty based on evidence. ''Might have'' = mere possibility.","''Might have'' is always wrong","''Must have'' is past tense of must"]','Must have + PP = logical deduction. Might have + PP = possibility (no commitment to truth).','medium'),
  (cid,41,144,'gap_fill','Given the scale of the damage, the disaster _____ (must/cause) losses of several billion dollars.','must have caused',NULL,'"Must have caused" = strong logical deduction based on visible evidence.','medium'),
  (cid,41,145,'gap_fill','The data _____ (may/record/passive) incorrectly — we _____ (need) to verify the original measurement protocols.','may have been recorded / need',NULL,'"May have been recorded" = passive modal perfect for uncertain past event.','hard'),
  (cid,41,146,'multiple_choice','Which modal perfect expresses CRITICAL JUDGMENT about a past action?','"The team should have disclosed the conflict of interest earlier."','["The team might have disclosed the conflict of interest earlier.","The team must have disclosed the conflict of interest earlier.","The team should have disclosed the conflict of interest earlier.","The team could have disclosed the conflict of interest earlier."]','"Should have + PP" = criticism/regret: they didn''t do it, but they ought to have.','medium'),
  (cid,41,147,'gap_fill','The early symptoms _____ (could/recognize/passive) sooner if more comprehensive screening protocols _____ (be) in place.','could have been recognized / had been',NULL,'"Could have been recognized" = unrealized past possibility (Type 3 conditional).','hard'),
  (cid,41,148,'gap_fill','The negotiators _____ (ought/reach) an agreement before the deadline, but political pressure from domestic constituencies _____ (make) this impossible.','ought to have reached / made',NULL,'"Ought to have + PP" = expectation not met. PS for what actually happened.','hard'),

  -- BLOCK 42: Modais passivos em pesquisa acadêmica
  (cid,42,149,'gap_fill','These results _____ (should/interpret/passive) with caution, given the small sample size and limited geographic scope of the study.','should be interpreted',NULL,'"Should be + past participle" = modal passive recommendation for data interpretation.','medium'),
  (cid,42,150,'gap_fill','Several potential confounds _____ (must/consider/passive) before drawing firm conclusions from the observed associations.','must be considered',NULL,'"Must be considered" = modal passive obligation for rigor.','medium'),
  (cid,42,151,'multiple_choice','Which modal passive is most appropriate for a RECOMMENDATION in an academic discussion section?','The limitations identified in this study should be addressed in future research.','["The limitations must have been addressed in future research.","The limitations will be addressed in future research (certainty — wrong for recommendation).","The limitations should be addressed in future research.","The limitations might be addressing in future research."]','"Should be addressed" = modal passive recommendation (not obligation, not certainty).','easy'),
  (cid,42,152,'gap_fill','The effect _____ (may/explain/passive) by a number of factors, several of which _____ (not/yet/adequately/test/passive).','may be explained / have not yet been adequately tested',NULL,'"May be explained" = hedged modal passive + PP negative passive for future research gap.','hard'),
  (cid,42,153,'gap_fill','The methodology _____ (can/apply/passive) across a range of contexts, though key parameters _____ (will/need/adapt/passive) to local conditions.','can be applied / will need to be adapted',NULL,'"Can be applied" = capacity passive + "will need to be adapted" = future passive obligation.','hard'),

  -- BLOCK 43: Semi-modais (ought to / need to / dare / used to)
  (cid,43,154,'multiple_choice','What is the difference between "need to" and "must" in academic recommendation context?','"Need to" is softer and more explanatory. "Must" is stronger and more categorical.','["They are identical","''Need to'' is more formal","''Need to'' is softer and more explanatory. ''Must'' is stronger and more categorical.","''Must'' always implies external obligation"]','"Need to" = functional necessity (situation requires it). "Must" = stronger directive.','medium'),
  (cid,43,155,'gap_fill','Governments _____ (ought/address) the structural causes of poverty rather than merely alleviating its symptoms.','ought to address',NULL,'"Ought to + base verb" = moral/logical obligation (slightly more formal than should).','medium'),
  (cid,43,156,'gap_fill','Research institutions _____ (used to/operate) in isolation, but collaborative networks have become standard practice in most fields.','used to operate',NULL,'"Used to + base verb" = habitual past state that no longer exists.','easy'),
  (cid,43,157,'gap_fill','Scientists rarely _____ (dare/publish) findings that contradicted established paradigms without risking professional ostracism.','dared to publish / dared publish',NULL,'"Dare to + base verb" OR "dare + base verb" = formal/literary use of semi-modal.','hard'),
  (cid,43,158,'multiple_choice','Which semi-modal construction is MOST FORMAL in academic writing?','Policy reforms ought to incorporate a comprehensive assessment of distributional consequences.','["Policy reforms should incorporate a comprehensive assessment (less formal than ought to in formal academic).","Policy reforms ought to incorporate a comprehensive assessment of distributional consequences.","Policy reforms need to incorporate a comprehensive assessment (functional/informal).","Policy reforms have to incorporate a comprehensive assessment (informal obligation)."]','"Ought to" = formal epistemic/moral obligation. Slightly more formal than "should."','hard'),

  -- BLOCK 44: Modais em hedging epistêmico avançado
  (cid,44,159,'gap_fill','The discrepancy between the two datasets _____ (may/reflect) differences in measurement methodology, though it _____ (could/also/result from) sampling biases.','may reflect / could also result from',NULL,'Epistemic modals for uncertain explanation: may + could for alternative possibilities.','medium'),
  (cid,44,160,'multiple_choice','Which modal best expresses INABILITY (rather than possibility or permission) in academic context?','Early computing systems could not process the volumes of data required for this analysis.','["Early computing systems might not process the data required.","Early computing systems could not process the volumes of data required for this analysis.","Early computing systems should not process the data required.","Early computing systems must not process the data required."]','"Could not" = inability (past). "Might not" = possibility. "Should not" = advice. "Must not" = prohibition.','medium'),
  (cid,44,161,'gap_fill','The mechanism by which X affects Y _____ (not/yet/fully/understand/passive) — several hypotheses _____ (propose/passive) but none _____ (confirm/passive) experimentally.','is not yet fully understood / have been proposed / has been confirmed',NULL,'Cannot passive + PP passive for proposals + PP passive negative for lack of confirmation.','hard'),
  (cid,44,162,'gap_fill','The findings _____ (could/have) implications for policy well beyond the immediate context of this study, though _____ (generalize) too broadly _____ (would/be) premature.','could have / generalizing / would be',NULL,'Could have implications + gerund subject + would be = hedged modal + conditional warning.','hard'),
  (cid,44,163,'multiple_choice','Which sentence uses modals for ACADEMIC HEDGING most skillfully?','The data may indicate a causal relationship, though alternative explanations cannot be ruled out at this stage.','["The data proves a causal relationship and alternative explanations are wrong.","The data may indicate a causal relationship, though alternative explanations cannot be ruled out at this stage.","The data might possibly perhaps suggest that there could maybe be some kind of causal relationship.","The data shows that there is definitely a causal relationship."]','May indicate (hedged claim) + cannot be ruled out (epistemic limitation) = balanced, calibrated.','medium'),

  -- BLOCK 45: TOEFL Reading
  (cid,45,164,'multiple_choice','[TOEFL Reading] "Early settlers may have underestimated the long-term consequences of their land management practices." The modal "may have underestimated" expresses:','A past possibility — the writer is uncertain whether this actually occurred.','["Certainty about past events","A past possibility — the writer is uncertain whether this actually occurred.","A past recommendation","Permission in the past"]','May have + PP = past possibility (not certain).','easy'),
  (cid,45,165,'gap_fill','[TOEFL Reading] "The species _____ (must/migrate) northward over thousands of years in response to glacial retreat, as fossil evidence _____ (suggest)." Best forms?','must have migrated / suggests',NULL,'"Must have migrated" = logical deduction from fossil evidence (present tense suggest).','medium'),
  (cid,45,166,'multiple_choice','[TOEFL Reading] "These findings should be replicated in larger populations before clinical recommendations are made." "Should be replicated" expresses:','A methodological recommendation for future research.','["Certainty about what will happen","A methodological recommendation for future research.","Permission to replicate the findings","An obligation imposed by law"]','"Should be + PP" = recommendation/advice in research context.','easy'),
  (cid,45,167,'gap_fill','[TOEFL Reading] "The collapse _____ (could/prevent/passive) if early warning systems _____ (be) in place and _____ (act/passive) upon promptly." Best modal forms?','could have been prevented / had been / been acted',NULL,'Type 3 conditional with modal passive + past perfect conditions.','hard'),

  -- BLOCK 46: TOEFL Speaking
  (cid,46,168,'production','[TOEFL Speaking — 45s] A reading discusses climate projections. The lecture notes important uncertainties. Summarize using modal hedging throughout.','',NULL,'The reading presents projections suggesting that global mean temperatures could rise by as much as 4°C above pre-industrial levels by 2100 if current emission trends continue. The lecture introduces significant epistemic hedging to these projections. The professor notes that while the physical science of greenhouse gas forcing is well-established, the precise magnitude of future warming cannot be specified with certainty because it depends on feedback mechanisms — particularly cloud dynamics and permafrost carbon release — that may amplify or moderate the primary warming signal in ways that current models cannot fully capture. The lecture suggests that the range of plausible outcomes ought to be communicated more honestly to policymakers, who may otherwise make overly precise plans based on central projections that should be interpreted as the middle of a wide probability distribution rather than as confident point estimates.','hard'),
  (cid,46,169,'production','[TOEFL Speaking — 45s] Discuss the lessons that could/should/ought to have been learned from past economic crises. Use modal perfects throughout.','',NULL,'Economic history provides a remarkably consistent set of lessons that policymakers ought to have internalized by now but have often failed to apply. The financial crisis of 2008, for instance, should not have been as surprising as it appeared to regulators and financial institutions, since several economists had clearly identified the risk dynamics building in the mortgage market years in advance. Regulatory bodies could have intervened earlier to constrain the growth of derivative instruments whose complexity made risk assessment nearly impossible. Stress-testing requirements should have been more stringent, and banks should not have been permitted to reduce capital buffers to the levels they maintained in the years before the crisis. These observations do not require hindsight: the theoretical frameworks that would have predicted the crisis had already been developed. The failure was not of knowledge but of institutional willingness to act on it.','hard'),

  -- BLOCK 47: TOEFL Writing
  (cid,47,170,'production','[TOEFL Writing — 150 words] Write a paragraph on artificial intelligence risks. Use: could/might/may (possibility), should be (recommendation), must (obligation), cannot (impossibility), ought to (moral necessity).','',NULL,'The deployment of artificial intelligence systems in high-stakes domains — criminal justice, medical diagnosis, financial lending — raises ethical concerns that must be addressed before adoption scales further. Systems trained on historical data may perpetuate and even amplify existing biases against underrepresented populations, producing outcomes that cannot be easily detected or challenged without significant technical expertise. Regulators ought to require independent auditing of any AI system used in decisions that significantly affect individuals'' life opportunities, and the results of such audits should be published in accessible form. High-risk AI applications could also be subject to mandatory impact assessments before deployment, analogous to the environmental impact assessments that govern large construction projects. Societies cannot afford to allow technological momentum to outpace the development of appropriate oversight mechanisms, particularly given that the consequences of AI error in domains like medical diagnosis might not become apparent until significant harm has occurred.','hard'),
  (cid,47,171,'production','[TOEFL Writing — Error Correction] Fix modal errors: "She must have not completed the assignment. They could avoided the mistake. The policy should has been reviewed earlier. Scientists used to discovered new species more regularly in the past. You ought studied more carefully."','',NULL,'must have not → must not have (negation: must not have + PP); could avoided → could have avoided (modal perfect: could + have + PP); should has been → should have been (modal perfect: should + have + PP); used to discovered → used to discover (used to + base verb); ought studied → ought to study OR ought to have studied (ought to + base verb, or ought to have + PP for past).','hard'),

  -- BLOCK 48: Consolidação final
  (cid,48,172,'production','[TOEFL Writing — 200 words] Write a paragraph on what can/should/must/ought to be done to address global water scarcity. Use modal variety throughout.','',NULL,'Global water scarcity represents one of the most serious resource challenges of the coming century, and addressing it will require action across multiple levels simultaneously. Governments in water-stressed regions must invest significantly in desalination, water recycling, and distribution infrastructure, since the costs of inaction — in terms of agricultural collapse, public health crises, and conflict — will far exceed the investment required. Agricultural practices ought to be reformed to reduce water intensity: crop varieties that require less irrigation could be developed and promoted through research investment and agricultural extension services, and water pricing reforms should ensure that irrigation water is priced at a level that reflects its true scarcity value rather than being effectively subsidized. International agreements on shared river systems and aquifer management may need to be strengthened, since transboundary water resources cannot be managed effectively by individual nations acting unilaterally. At the household and municipal level, conservation measures could achieve significant reductions in consumption if combined with appropriate incentives and public education. Water scarcity problems, while serious, ought not to be treated as inevitable or insolvable — historical experience suggests that well-designed policy and appropriate investment can substantially reduce vulnerability even in highly water-stressed contexts.','hard'),
  (cid,48,173,'production','[TOEFL Speaking — 60s] Discuss what lessons from the COVID-19 pandemic should/could/must/ought to be applied to future pandemic preparedness. Use modal variety including modal perfects.','',NULL,'The COVID-19 pandemic exposed a series of systemic failures in global health preparedness that ought to be carefully analyzed and addressed before the next major outbreak occurs. Surveillance systems that should have detected the emergence of novel pathogens earlier proved inadequate, and the protocols for sharing genomic sequence data between countries could have been significantly faster had pre-negotiated agreements been in place. Vaccine manufacturing capacity must be distributed more equitably across the world''s regions; the concentration of production in a small number of countries meant that wealthy nations could secure supplies that should have been allocated in part according to vulnerability rather than purchasing power. Governments ought to maintain larger stockpiles of personal protective equipment and essential medical supplies, since the procurement failures of the early pandemic could have been avoided had contingency inventories been maintained. International institutions must be given both the mandate and the resources to conduct rapid-response investigations of emerging outbreaks, since the hesitations and political sensitivities that slowed the early pandemic response cannot be permitted to recur. These lessons are not new — many of them were identified after SARS in 2003 — and the failure to act on them may prove even more costly if the next pandemic is more transmissible or more lethal.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
